import React, { useState } from "react";
import "./App.css";
import Question from "./components/Question";

// Array of quiz questions with answer choices
const questions = [
  {
    questionText: "What is the capital of France?",
    options: ["Berlin", "Madrid", "Paris", "Rome"],
    correctAnswer: "Paris",
  },
  {
    questionText: "What is 2 + 2?",
    options: ["3", "4", "5", "6"],
    correctAnswer: "4",
  },
  {
    questionText: "Which planet is known as the Red Planet?",
    options: ["Earth", "Mars", "Jupiter", "Venus"],
    correctAnswer: "Mars",
  },
  {
    questionText: "What is the largest ocean on Earth?",
    options: ["Atlantic", "Indian", "Southern", "Pacific"],
    correctAnswer: "Pacific",
  },
  {
    questionText: "Who wrote 'To Kill a Mockingbird'?",
    options: ["Harper Lee", "J.K. Rowling", "Mark Twain", "Ernest Hemingway"],
    correctAnswer: "Harper Lee",
  },
];

function App() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [score, setScore] = useState(0);
  const [quizCompleted, setQuizCompleted] = useState(false);
  const [answered, setAnswered] = useState(false);
  const [correct, setCorrect] = useState(false);

  const handleAnswerSelection = (answer) => {
    setSelectedAnswer(answer);
    setAnswered(true);
    setCorrect(answer === questions[currentQuestion].correctAnswer);
  };

  const handleNextQuestion = () => {
    if (selectedAnswer === questions[currentQuestion].correctAnswer) {
      setScore(score + 1);
    }
    setAnswered(false);
    setSelectedAnswer(null);

    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      setQuizCompleted(true);
    }
  };

  const calculatePercentage = () => {
    return ((score / questions.length) * 100).toFixed(2);
  };

  const progress = ((currentQuestion + 1) / questions.length) * 100;

  if (quizCompleted) {
    return (
      <div className="result">
        <h2>Quiz Completed!</h2>
        <p>
          You answered {score} out of {questions.length} correctly.
        </p>
        <p>Score: {calculatePercentage()}%</p>
        <div className="score-box">
          Final Score: {score}/{questions.length}
        </div>
      </div>
    );
  }

  return (
    <div className="quiz-container">
      <h1>Quiz App</h1>

      {/* Progress bar */}
      <div className="progress-bar">
        <div
          className="progress-bar-filled"
          style={{ width: `${progress}%` }}
        />
      </div>

      <Question
        question={questions[currentQuestion]}
        selectedAnswer={selectedAnswer}
        handleAnswerSelection={handleAnswerSelection}
        handleNextQuestion={handleNextQuestion}
        correct={correct}
        answered={answered}
      />

      {/* Next button */}
      <button
        onClick={handleNextQuestion}
        className={`next-btn ${answered ? "active" : ""}`}
        disabled={!answered}
      >
        Next
      </button>
    </div>
  );
}

export default App;
